const [light, dark, ...colors] = ["#fffbe6", "#050505", "#abcd5e", "#29ac9f", "#14976b", "#b3dce0", "#62b6de", "#2b67af", "#f589a3", "#ef562f", "#fc8405", "#f9d531"]

let headingFont
let bodyFont

function preload() {
	headingFont = loadFont('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/default_texture.png')
	bodyFont = loadFont('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/default_texture.png')
}

function setup() {
	createCanvas(800, 800, WEBGL)
	background(100);
}

function draw() {
	background(255)
	translate(-width/2, -height/2)
	const t = millis()
	const offY = t * 0.0005
	const numTiles = 5;

	noStroke()
	for (let u = 0; u < numTiles; u++) {
		for (let v = -2; v < numTiles + 2; v++) {
			push()
			const c = color(colors[floor(noise(u*10, 10*(v - floor(offY))) * colors.length)])

			const tStart = lerp(-2, 1, noise(u*10, 10*(v - floor(offY)), 1000))
			const tEnd = tStart + lerp(0.5, 3, noise(u*10, 10*(v - floor(offY)), 1000))
			const progress = Ease.easeOutElastic(map(v + (offY % 1), tStart, tEnd, 0, 1, true))
			fill(red(window.color(c)), green(window.color(c)), blue(window.color(c)), 255 * constrain(progress, 0, 1))
			translate(
				map(u + 0.5, 0, numTiles, 0, width),
				map(v + 0.5 + (offY % 1), 0, numTiles, 0, height) - 300 * (1-progress),
				lerp(-400, 0, progress)
			)
			plane(
				width / numTiles,
				height / numTiles
			)
			pop()
		}
	}
	clearDepth()

	push()
	fill(255, 150)
	rect(0, 0, width, height)
	pop()

	push()
	fill(dark)
	textFont(headingFont)
	textAlign(LEFT, CENTER)
	textSize(120)
	textLeading(120)
	text('p5*js\nCommunity\nSketches', 40, height/2 - 70)
	pop()

	push()
	fill(dark)
	textFont(bodyFont)
	textSize(35)
	textAlign(LEFT, TOP)
	text('Feature your sketch on the new p5.js website', 40, height/2 + 140)
	text('Open Call', 40, 40)
	textAlign(RIGHT, TOP)
	text('Submit by March 31', width - 40, 40)
	textAlign(LEFT, BOTTOM)
	text('→ openprocessing.org/curation/87594', 40, height - 40)
	pop()
}
